{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Theophylline, a methylated xanthine heterocycle with high assay-transfer relevance, showed absolute oral bioavailability of 0.80 in humans, supporting high F for the similarly methylated heteroaromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Pirfenidone, an N-phenyl methylated pyridone structurally close to the query's N-phenyl heterocycle, is reported to have high oral bioavailability in humans and nonclinical species.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Trazodone, a high-transfer N-aryl heterocyclic drug, had absolute oral bioavailability of 63±4% in healthy subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Desipramine, despite being the lower-end analogue, showed mean absolute oral bioavailability of 38% in healthy volunteers, still clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Flibanserin, an N-aryl heterocycle with high transfer relevance, had absolute oral bioavailability of 33% in premenopausal women, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Trametinib, a complex N-heteroaromatic drug, showed mean absolute oral bioavailability of 72.3% in patients, reinforcing that N-aryl heterocycles in this chemical space are generally well absorbed orally.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability values well above 20%, ranging from about 33% to complete absorption. The query's small, moderately polar N-phenyl methylated heterocycle is consistent with these high-bioavailability compounds, and no evidence supports low F.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule itself.",
    "The query is a metabolite-like structure; direct human F data for the exact compound would remove residual uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

